% Repeatability: median of the filtered displacements towards the magnet
% (-X component, 0.3-8 um) for each position of the seven trials performed
% on the same sample of each hydrogel, mean of the medians of the three
% positions per trial, and mean, SD and CV of the seven trials.
%
% Input: tp_01.mat files generated by TFMLAB (7 trials x 3 positions per hydrogel).
% Outputs: repeatability_7trials.xlsx, repeatability_tables.tex and one
% figure per hydrogel (repeatability_peg12 / repeatability_peg15).

clear
clc
close all

%% Paths (built automatically: 7 trials x 3 positions per hydrogel)
base = 'path/to/data';   % edit the path
tail = fullfile('D_2_displacements', 'beads', 'tp_01.mat');

% folder, file prefix, output name and colour of each hydrogel
gel(1).label  = 'PEG-W 1.2%';
gel(1).tex    = 'PEG-W 1.2\%';
gel(1).folder = fullfile(base, 'peg12', 'SAMPLE_A_7trials');
gel(1).prefix = 'peg12_sample2';
gel(1).out    = 'repeatability_peg12';
gel(1).color  = [0.11 0.25 0.45];   % dark blue
gel(2).label  = 'PEG-W 1.5%';
gel(2).tex    = 'PEG-W 1.5\%';
gel(2).folder = fullfile(base, 'peg15', 'SAMPLE_A_7trials');
gel(2).prefix = 'peg15_sample4';
gel(2).out    = 'repeatability_peg15';
gel(2).color  = [0.80 0.35 0.10];   % orange

nTrials = 7;
nPos    = 3;
trials  = 1:nTrials;

%% Filter limits (um)
minVal = 0.3;
maxVal = 8;

%% Median of each position of each trial (-X component, filtered)
medPos = NaN(2, nTrials, nPos);   % gel x trial x position
nKept  = zeros(2, nTrials, nPos);

for g = 1:2
    fprintf('\n=== %s ===\n', gel(g).label)
    for t = 1:nTrials
        for p = 1:nPos
            f = fullfile(gel(g).folder, sprintf('pos%d', p), ...
                sprintf('%s_trial%d_pos%d', gel(g).prefix, t, p));
            f = fullfile(f, tail);
            S = load(f);
            X = S.dispField.X(:);

            X = X(~isnan(X));                       % remove NaNs
            X = -X(X < 0);                          % -X component (towards the magnet)
            X = X(X >= minVal & X <= maxVal);       % filter step

            nKept(g, t, p) = numel(X);
            if isempty(X)
                warning('No points left after filtering: %s', f)
            else
                medPos(g, t, p) = median(X);
            end
            fprintf('  Trial %d, pos%d: median = %.3f um (N = %d)\n', ...
                t, p, medPos(g, t, p), nKept(g, t, p))
        end
    end
end

%% Value of each trial = mean of the medians of the 3 positions
trialVal = mean(medPos, 3, 'omitnan');     % gel x trial

%% Repeatability: mean, SD and CV of the 7 trial values, for each hydrogel
fprintf('\n=== Repeatability (7 trials) ===\n')
repMean = zeros(1, 2);  repSD = zeros(1, 2);  repCV = zeros(1, 2);
for g = 1:2
    repMean(g) = mean(trialVal(g, :), 'omitnan');
    repSD(g)   = std(trialVal(g, :), 0, 'omitnan');
    repCV(g)   = 100 * repSD(g) / repMean(g);
    fprintf('%s: %.2f +/- %.2f um, CV = %.0f %%\n', gel(g).label, repMean(g), repSD(g), repCV(g))
end

%% Excel with all values
T = table();
for g = 1:2
    for t = 1:nTrials
        T = [T; {string(gel(g).label), t, medPos(g,t,1), medPos(g,t,2), medPos(g,t,3), ...
                 trialVal(g,t), nKept(g,t,1), nKept(g,t,2), nKept(g,t,3)}]; %#ok<AGROW>
    end
end
T.Properties.VariableNames = {'Hydrogel','Trial','Median_pos1_um','Median_pos2_um', ...
    'Median_pos3_um','Mean_of_medians_um','N_pos1','N_pos2','N_pos3'};
R = table(string({gel.label})', repMean', repSD', repCV', ...
    'VariableNames', {'Hydrogel','Mean_of_trials_um','SD_um','CV_percent'});
disp(T); disp(R)
writetable(T, 'repeatability_7trials.xlsx', 'Sheet', 'Trials')
writetable(R, 'repeatability_7trials.xlsx', 'Sheet', 'Repeatability')

%% LaTeX tables for the appendix (one per hydrogel), saved to a .tex file
fid = fopen('repeatability_tables.tex', 'w');
for g = 1:2
    fprintf(fid, '\\begin{table}[H]\n\\centering\n');
    fprintf(fid, ['\\caption{Median displacement towards the magnet ($x$-component) ' ...
        'of each position in the seven trials performed on the same sample of the %s hydrogel, ' ...
        'after the filtering step (0.3--8~\\textmu m), and mean of the medians of the three ' ...
        'positions of each trial. The last rows present the mean $\\pm$ SD and the coefficient ' ...
        'of variation (CV) of the seven trials.}\n'], gel(g).tex);
    fprintf(fid, '\\label{tab:repeatability_%s}\n', gel(g).out(end-4:end));
    fprintf(fid, '\\begin{tabular}{ccccc}\n\\toprule\n');
    fprintf(fid, ['\\textbf{Trial} & \\textbf{Position 1 (\\textmu m)} & ' ...
        '\\textbf{Position 2 (\\textmu m)} & \\textbf{Position 3 (\\textmu m)} & ' ...
        '\\textbf{Mean of medians (\\textmu m)} \\\\\n\\midrule\n']);
    for t = 1:nTrials
        fprintf(fid, '%d & %.3f & %.3f & %.3f & %.3f \\\\\n', ...
            t, medPos(g,t,1), medPos(g,t,2), medPos(g,t,3), trialVal(g,t));
    end
    fprintf(fid, '\\midrule\n');
    fprintf(fid, '\\multicolumn{4}{l}{Mean $\\pm$ SD of the seven trials} & %.2f $\\pm$ %.2f \\\\\n', ...
        repMean(g), repSD(g));
    fprintf(fid, '\\multicolumn{4}{l}{CV (\\%%)} & %.0f \\\\\n', repCV(g));
    fprintf(fid, '\\bottomrule\n\\end{tabular}\n\\end{table}\n\n');
end
fclose(fid);
fprintf('\nLaTeX tables saved to repeatability_tables.tex\n')

%% Figures: one per hydrogel
yMax = max(trialVal(:), [], 'omitnan') * 1.3;
for g = 1:2
    c = gel(g).color;
    fig = figure('Color','w', 'Units','centimeters', 'Position',[2 2 12 8]);
    ax = axes(fig);
    hold(ax, 'on')

    % shaded band: mean +/- SD of the 7 trials
    hBand = fill(ax, [0.5 7.5 7.5 0.5], ...
        [repMean(g)-repSD(g) repMean(g)-repSD(g) repMean(g)+repSD(g) repMean(g)+repSD(g)], ...
        c, 'FaceAlpha', 0.12, 'EdgeColor', 'none');
    % dashed line: mean of the 7 trials
    hMean = yline(ax, repMean(g), '--', 'Color', c, 'LineWidth', 1);

    % points: value of each trial (mean of the medians of the 3 positions)
    hPts = plot(ax, trials, trialVal(g,:), '-o', 'Color', c, 'MarkerFaceColor', c, ...
        'MarkerSize', 6, 'LineWidth', 1.2);

    xlim(ax, [0.5 7.5])
    ylim(ax, [0 yMax])
    xticks(ax, trials)
    xlabel(ax, 'Trial')
    ylabel(ax, 'Median displacement towards the magnet (µm)', 'Interpreter', 'none')
    set(ax, 'FontName','Arial', 'FontSize',10, 'LineWidth',1, 'TickDir','out', 'Box','off')

    legend(ax, [hPts hMean], {'Mean of the 3 positions per trial', 'Mean of the 7 trials \pm SD'}, ...
        'Location','best', 'Box','off', 'FontName','Arial', 'FontSize',9)

    exportgraphics(fig, [gel(g).out '.png'], 'Resolution', 300)
    exportgraphics(fig, [gel(g).out '.pdf'], 'ContentType','vector')
end
